from __future__ import annotations

def kv_cache_bytes(layers: int, seq_len: int, kv_heads: int, head_dim: int, bytes_per_value: int) -> int:
    """Return bytes for K and V cache; all dimensions must be positive integers."""
    values = (layers, seq_len, kv_heads, head_dim, bytes_per_value)
    if any(isinstance(v, bool) or not isinstance(v, int) or v <= 0 for v in values):
        raise ValueError("all KV-cache dimensions must be positive integers")
    return 2 * layers * seq_len * kv_heads * head_dim * bytes_per_value


def test_kv_cache_bytes() -> None:
    assert kv_cache_bytes(1, 1, 1, 1, 1) == 2
    assert kv_cache_bytes(2, 3, 4, 5, 2) == 480
    for bad in ((0,1,1,1,1), (1,0,1,1,1), (1,1,0,1,1), (1,1,1,0,1), (1,1,1,1,0), (-1,1,1,1,1)):
        try:
            kv_cache_bytes(*bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"accepted invalid input: {bad}")


if __name__ == "__main__":
    test_kv_cache_bytes()
```

The formula counts both K and V tensors; it assumes one value of the stated byte width per cache element and no allocator padding, metadata, replication, quantization overhead, or fragmentation. Integer arithmetic is exact and O(1) time/space; the returned integer can still be large, so callers should check platform allocation limits separately.

